import os, sys; sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))
from lib import *
import lib as h, sys, datetime as dt
TEH = TEH_P
iso = lambda d: (dt.datetime.now(dt.timezone.utc) + dt.timedelta(days=d)).isoformat()
psql("delete from campaigns where title like 'آزمون پویش%'; delete from rahyar_positions where title='راهیار استانی آزمون پویش'; delete from cores where name='هستهٔ آزمون پویش'")
hq = staff(); a = login('09126000002'); b = login('09126000003'); c = login('09126000004'); pr = login('09126000001')
A = psql("select id from users where first_name='عضو' and last_name='یکم'"); Bid = psql("select id from users where first_name='عضو' and last_name='دوم'"); PR = psql("select id from users where first_name='مدیر' and last_name='سازمان'")
NET = psql("select id from networks where kind='BANOUR' limit 1")
psql(f"insert into cores (id,name,network_id,leader_id,invite_code) values ('core-smk8','هستهٔ آزمون پویش','{NET}','{A}','hsmk8xx'); insert into core_memberships (core_id,user_id) values ('core-smk8','{A}'),('core-smk8','{Bid}')")
psql(f"insert into rahyar_positions (id,gender,layer,title,holder_id,province_id) values ('pos-smk8','FEMALE','PROVINCIAL','راهیار استانی آزمون پویش','{PR}','{TEH}')")
camp = lambda t, **k: {'title': t, 'summary': 'یک پویش آزمایشی برای سنجش سامانه', 'scope': 'NATIONAL', 'startsAt': iso(-0.5), 'endsAt': iso(9), 'goal': 10, 'tasks': [{'title': 'کار اول'}, {'title': 'کار دوم', 'body': 'توضیح'}], **k}
print('ساخت')
r = c.post(f'{B}/manage/campaigns', json=camp('آزمون پویش ۰')); ok(r.status_code == 403, 'کنشگر عادی نمی‌سازد: ' + r.json().get('message', ''))
r = pr.post(f'{B}/manage/campaigns', json=camp('آزمون پویش ۰')); ok(r.status_code == 403, 'راهیار استانی پویش کشوری نمی‌سازد: ' + r.json().get('message', ''))
r = hq.post(f'{B}/manage/campaigns', json=camp('آزمون پویش ۱', endsAt=iso(-1))); ok(r.status_code == 400, 'پایان پیش از شروع رد شد')
r = hq.post(f'{B}/manage/campaigns', json=camp('آزمون پویش ۱')); ok(r.ok, 'ستاد پویش کشوری ساخت', r.text); C1 = r.json()['id']
ok(not any(x['id'] == C1 for x in a.get(f'{B}/campaigns').json()), 'پیش‌نویس دیده نمی‌شود')
r = hq.post(f'{B}/manage/campaigns/{C1}/publish').json(); ok(r.get('notified', 0) > 3, 'انتشار و اعلان', r)
ok(any(x['id'] == C1 for x in a.get(f'{B}/campaigns').json()), 'کنشگر می‌بیند')
print('پیوستن و کار')
d = a.get(f'{B}/campaigns/{C1}').json(); T1, T2 = d['tasks'][0]['id'], d['tasks'][1]['id']
ok(a.post(f'{B}/campaigns/{C1}/tasks/{T1}', json={}).status_code == 400, 'بی‌پیوستن کار ثبت نمی‌شود')
ok(any(k['id'] == 'core-smk8' for k in d['cores']), 'مسئول هسته گزینهٔ پیوستن هسته‌ای دارد')
r = a.post(f'{B}/campaigns/{C1}/join-core', json={'coreId': 'core-smk8'}).json(); ok(r.get('added') == 2, 'هسته یک‌جا پیوست', r)
ok(b.post(f'{B}/campaigns/{C1}/join-core', json={'coreId': 'core-smk8'}).status_code == 403, 'غیرمسئول هسته را نمی‌پیوندد')
ok(a.post(f'{B}/campaigns/{C1}/tasks/{T1}', json={'note': 'با دو نوجوان حرف زدم'}).ok, 'کار با یادداشت')
ok(b.post(f'{B}/campaigns/{C1}/tasks/{T1}', json={}).ok and b.post(f'{B}/campaigns/{C1}/tasks/{T2}', json={}).ok, 'عضو هسته دو کار')
d = a.get(f'{B}/campaigns/{C1}').json(); ok(d['totals'] == {'members': 2, 'done': 3, 'cores': 1} and d['badge'] and d['tasks'][0]['note'] == 'با دو نوجوان حرف زدم', 'شمار جمعی، نشان و یادداشت خصوصی', d['totals'])
ok(psql(f"select note like 'enc:%' from campaign_done where task_id='{T1}' and user_id='{A}'") == 't', 'یادداشت رمزگذاری شده')
db = b.get(f'{B}/campaigns/{C1}').json(); ok(db['viaCore'] == 'هستهٔ آزمون پویش' and db['tasks'][0]['note'] is None, 'یادداشت دیگران دیده نمی‌شود')
tehran = [p for p in d['map'] if p['name'] == 'تهران'][0]; ok(tehran['members'] == 2 and tehran['done'] == 3, 'نقشهٔ استان‌ها')
ok(b.delete(f'{B}/campaigns/{C1}/tasks/{T2}').ok, 'برداشتن علامت')
bg = a.get(f'{B}/campaigns/badges').json(); ok(any(x['id'] == C1 for x in bg), 'نشان مشارکت در «من»')
m = hq.get(f'{B}/manage/campaigns/{C1}').json(); ok(m['totals']['done'] == 2 and m['perDay'] and 'note' not in str(m['tasks']), 'آمار سازنده بی‌نام', m['totals'])
ok('عضو' not in str(m), 'نام شرکت‌کنندگان در آمار نیست')
print('استانی')
r = pr.post(f'{B}/manage/campaigns', json=camp('آزمون پویش ۲', scope='PROVINCE', provinceId=TEH)); ok(r.ok, 'راهیار استانی برای استان خودش', r.text); C2 = r.json()['id']
other = psql("select id from provinces where id <> '%s' limit 1" % TEH)
ok(pr.post(f'{B}/manage/campaigns', json=camp('آزمون پویش ۳', scope='PROVINCE', provinceId=other)).status_code == 403, 'استان دیگر نه')
pr.post(f'{B}/manage/campaigns/{C2}/publish')
ok(a.post(f'{B}/campaigns/{C2}/join').ok, 'ساکن استان می‌پیوندد')
r = pr.patch(f'{B}/manage/campaigns/{C2}', json=camp('آزمون پویش ۲', scope='PROVINCE', provinceId=other)); ok(r.status_code in (400, 403), 'دامنهٔ پویش منتشرشده عوض نمی‌شود: ' + r.json().get('message', ''))
r = pr.patch(f'{B}/manage/campaigns/{C2}', json=camp('آزمون پویش ۲ ویرایش', scope='PROVINCE', provinceId=TEH, tasks=[{'title': 'کار تازه'}])); ok(r.ok, 'ویرایش و جایگزینی کارها (کاری انجام نشده)', r.text)
ok(pr.post(f'{B}/manage/campaigns/{C2}/cancel').ok, 'لغو')
ok(a.post(f'{B}/campaigns/{C2}/join').status_code == 400, 'پیوستن به پویش لغوشده نه')
ok(psql("select count(*) from notifications n join users u on u.id=n.user_id where u.first_name='عضو' and u.last_name='یکم' and n.title like '%لغو شد%'") >= '1', 'اعلان لغو به شرکت‌کننده')
print('\nنتیجه:', 'همه درست' if not h.fails else f'{h.fails} خطا'); sys.exit(1 if h.fails else 0)
